/* ============================================================
   ⑦ 输入栏上方的提示条(沿用第二套)
   ============================================================ */
:root {
  --tip-bg: rgba(255, 255, 255, 0.88);
  --tip-border: 1px solid #e2e2e2;
  --tip-radius: 10px;            /* 四角圆润程度,想更方就调小 */
  --tip-color: #9a9a9a;
  --tip-shadow: 0 2px 8px rgba(0, 0, 0, 0.04);
  --tip-gap: 6px;                /* 条与条之间的距离 */
  --tip-pad: 8px 12px;
}

:root {
  --tip-gap: 8px;
  /* 各条的大概高度,只用来算"往上叠多少",不是固定高度 */
  --h-reply: 46px;
  --h-sendas: 38px;
  --h-qrai: 70px;
}

/* ① 底栏作为定位基准,提示条悬浮在它上方 */
.chat-detail-screen .input-area-custom {
  position: relative !important;
  overflow: visible !important;
  /* 记录当前有哪些条在,用来算叠放高度 */
  --r: 0; --s: 0; --q: 0;
}
.input-area-custom:has(.input-reply-preview-bar) { --r: 1; }
.input-area-custom:has(.input-sendas-bar)        { --s: 1; }
.input-area-custom:has(.nuo-qrai-hint, .nuo-qrai-panel) { --q: 1; }

.input-reply-preview-bar,
.input-sendas-bar,
.nuo-qrai-hint,
.nuo-qrai-panel,
.nuo-console-shell {
  position: absolute !important;
  left: 14px !important;
  right: 14px !important;
  top: auto !important;
  margin: 0 !important;
  height: auto !important;          /* 高度跟内容走 */
  max-height: none !important;
  transform: none !important;
  z-index: 30 !important;
}

/* 从下往上依次:引用预览 → 发送身份/旁白 → AI 回覆建议 → 控制台 */
.input-reply-preview-bar {
  bottom: calc(100% + var(--tip-gap)) !important;
}
.input-sendas-bar {
  bottom: calc(100% + var(--tip-gap) + var(--r) * (var(--h-reply) + var(--tip-gap))) !important;
}
.nuo-qrai-hint,
.nuo-qrai-panel {
  bottom: calc(100% + var(--tip-gap)
    + var(--r) * (var(--h-reply) + var(--tip-gap))
    + var(--s) * (var(--h-sendas) + var(--tip-gap))) !important;
}
.nuo-console-shell {
  bottom: calc(100% + var(--tip-gap)
    + var(--r) * (var(--h-reply) + var(--tip-gap))
    + var(--s) * (var(--h-sendas) + var(--tip-gap))
    + var(--q) * (var(--h-qrai) + var(--tip-gap))) !important;
}

/* ② 引用预览:去掉前面的竖杠 */
.chat-detail-screen {
  --reply-bar-accent-border: none;
  --reply-bar-content-padding-left: 0px;
}
.input-reply-preview-bar,
.input-reply-preview-content,
.input-reply-preview-name,
.input-reply-preview-text {
  border-left: none !important;
  box-shadow: none !important;
}
.input-reply-preview-bar { border: var(--tip-border) !important; }
.input-reply-preview-content { padding-left: 0 !important; }

/* ② 引用预览 */
.chat-detail-screen {
  --reply-bar-bg: var(--tip-bg);
  --reply-bar-radius: var(--tip-radius);
  --reply-bar-border: var(--tip-border);
  --reply-bar-shadow: var(--tip-shadow);
  --reply-bar-padding: var(--tip-pad);
  --reply-bar-backdrop: none;
  --reply-bar-accent: #bdbdbd;
  --reply-bar-text-color: var(--tip-color);
}
.input-reply-preview-bar {
  background: var(--tip-bg) !important;
  border: var(--tip-border) !important;
  border-radius: var(--tip-radius) !important;
  box-shadow: var(--tip-shadow) !important;
  padding: var(--tip-pad) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
  color: var(--tip-color) !important;
}

/* ③ 以角色身份发送 / 旁白模式 */
.chat-detail-screen {
  --sendas-bar-radius: var(--tip-radius);
  --sendas-bar-shadow: var(--tip-shadow);
  --sendas-char-bg: var(--tip-bg);
  --sendas-char-color: var(--tip-color);
  --sendas-char-border: #e2e2e2;
  --sendas-narration-bg: var(--tip-bg);
  --sendas-narration-color: var(--tip-color);
  --sendas-narration-border: #e2e2e2;
}
.input-sendas-bar,
.input-sendas-char-bar,
.input-sendas-narration-bar {
  background: var(--tip-bg) !important;
  color: var(--tip-color) !important;
  border: var(--tip-border) !important;
  border-radius: var(--tip-radius) !important;
  box-shadow: var(--tip-shadow) !important;
  padding: var(--tip-pad) !important;
  backdrop-filter: none !important;
  -webkit-backdrop-filter: none !important;
}

/* ④ 查看控制台:入口按钮、token 按钮、展开面板 */
.chat-detail-screen {
  --console-toggle-bg: var(--tip-bg);
  --console-toggle-color: var(--tip-color);
  --console-toggle-border: var(--tip-border);
  --console-toggle-radius: var(--tip-radius);
  --console-toggle-shadow: var(--tip-shadow);
  --console-token-bg: var(--tip-bg);
  --console-token-color: var(--tip-color);
  --console-token-border: var(--tip-border);
  --console-token-radius: var(--tip-radius);
  --console-token-shadow: var(--tip-shadow);
  --console-panel-bg: rgba(255, 255, 255, 0.94);
  --console-panel-color: var(--tip-color);
  --console-panel-border: var(--tip-border);
  --console-panel-radius: var(--tip-radius);
  --console-panel-shadow: var(--tip-shadow);
  --console-panel-backdrop: none;
  --console-shell-position: relative;
}
.nuo-console-shell { margin-bottom: var(--tip-gap) !important; }
.nuo-console-toggle-btn,
.nuo-console-token-btn {
  background: var(--tip-bg) !important;
  color: var(--tip-color) !important;
  border: var(--tip-border) !important;
  border-radius: var(--tip-radius) !important;
  box-shadow: var(--tip-shadow) !important;
  background-image: none !important;
}

/* ⑤ AI 帮我回覆的提示条和面板,一并统一 */
.chat-detail-screen {
  --qrai-hint-bg: var(--tip-bg);
  --qrai-hint-color: var(--tip-color);
  --qrai-hint-border: var(--tip-border);
  --qrai-hint-radius: var(--tip-radius);
  --qrai-hint-shadow: var(--tip-shadow);
  --qrai-hint-backdrop: none;
  --qrai-panel-bg: var(--tip-bg);
  --qrai-panel-border: var(--tip-border);
  --qrai-panel-radius: var(--tip-radius);
  --qrai-panel-shadow: var(--tip-shadow);
  --qrai-panel-backdrop: none;
}

/* ============================================================
   ⑧ 翻译:隐藏「查看翻译」,点气泡展开 → 白字黑描边(沿用第二套)
   ============================================================ */

/* 1. 气泡内:翻译区脱离排版流,不占任何高度 */
.msg-translation-wrapper {
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  border: none !important;
  overflow: visible !important;
  pointer-events: none !important;   /* 自己不挡点击,只让里面的按钮接收 */
  z-index: 3 !important;
}
.msg-translation-wrapper .msg-translation-content {
  display: none !important;
}

/* 2. 按钮:不可见,但铺满整个气泡,可点击 */
.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
}
.msg-translation-btn {
  display: block !important;
  position: absolute !important;
  top: 0 !important;
  left: 0 !important;
  width: 100% !important;
  height: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  background: transparent !important;
  border: none !important;
  box-shadow: none !important;
  font-size: 0 !important;
  color: transparent !important;
  opacity: 1 !important;
  overflow: hidden !important;
  cursor: pointer !important;
  pointer-events: auto !important;
  z-index: 3 !important;
}
.msg-translation-btn *,
.msg-translation-btn svg,
.msg-translation-btn span {
  display: none !important;
}
.msg-translation-btn::before,
.msg-translation-btn::after {
  display: none !important;
  content: none !important;
}
.bubble-them-custom,
.bubble-me-custom {
  position: relative !important;
  gap: 0 !important;
  row-gap: 0 !important;
}

/* 3. 气泡外:点开后出现的独立翻译块 */
.msg-translation-detached {
  display: block !important;
  margin-top: 6px !important;
  max-width: 100% !important;
  width: fit-content !important;
  min-width: 0 !important;
  box-sizing: border-box !important;
}

/* 4. 内容层(会被下面第 5 段覆盖成纯文字) */
.msg-translation-detached-content {
  background: #ffffff !important;
  color: #1D1B37 !important;
  padding: 5px 16px !important;
  border: 1.5px solid #1D1B37 !important;
  border-radius: 10px !important;
  box-shadow: 0 2px 6px rgba(29,27,55,0.06) !important;
  font-size: 13px !important;
  line-height: 1.5 !important;
  word-break: break-word !important;
  position: relative !important;
}
.msg-translation-detached-me .msg-translation-detached-content {
  background: #FFF4FA !important;
}

/* 5. 翻译文字:去气泡,粗体 + 白字黑描边 */
.msg-translation-detached-content,
.msg-translation-detached-me .msg-translation-detached-content,
.msg-translation-detached-them .msg-translation-detached-content {
  background: transparent !important;
  border: none !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  padding: 2px 0 !important;
  font-size: 13px !important;
  font-weight: 700 !important;
  line-height: 1.5 !important;
  letter-spacing: 0.5px !important;
  word-break: break-word !important;
  position: relative !important;

  color: #ffffff !important;
  -webkit-text-fill-color: #ffffff !important;
  -webkit-text-stroke: 2.5px #1D1B37 !important;
  paint-order: stroke fill !important;
  text-shadow: none !important;
}

/* 我方靠右 */
.msg-translation-detached-me .msg-translation-detached-content {
  text-align: right !important;
}

/* ===== 翻译文字:上移 + 右移,悬浮在气泡边缘 ===== */
.msg-translation-detached {
  margin-top: -4px !important;
  position: relative !important;
  z-index: 6 !important;
  pointer-events: none !important;
}

/* 对方:往上、往右 */
.msg-translation-detached-them {
  transform: translate(18px, -10px) !important;
}

/* 我方:往上,向左浮 */
.msg-translation-detached-me {
  transform: translate(-18px, -10px) !important;
}

